export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatItem {
  kind: 'seat';
  row: number;
  column: number;
  state: SeatState;
}

export interface CouchItem {
  kind: 'couch';
  row: number;
  start: number;
  end: number;
  state: SeatState;
}

export type AuditoriumItem = SeatItem | CouchItem;

/** One row of the auditorium: the three blocks between the two aisles, left to right. */
export interface AuditoriumRow {
  number: number;
  blocks: AuditoriumItem[][];
}

const ROW_COUNT = 15;
const COUCH_ROW = 15;
/** Rows 1 to 10 have no seats in columns 1 to 4: the entrance. */
const ENTRANCE_LAST_ROW = 10;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

export function seatIdentifier(row: number, column: number): string {
  return `R${row}C${column}`;
}

/** Builds the auditorium: rows 1 to 15, each split into blocks of columns 1–4, 5–20 and 21–24. */
export function buildAuditorium(occupiedSeats: ReadonlySet<string>): AuditoriumRow[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const number = index + 1;
    const left = number <= ENTRANCE_LAST_ROW ? [] : itemsFor(number, 1, 4, occupiedSeats);
    return {
      number,
      blocks: [left, itemsFor(number, 5, 20, occupiedSeats), itemsFor(number, 21, 24, occupiedSeats)],
    };
  });
}

function itemsFor(row: number, firstColumn: number, lastColumn: number, occupied: ReadonlySet<string>): AuditoriumItem[] {
  const items: AuditoriumItem[] = [];
  if (row === COUCH_ROW) {
    for (let start = firstColumn; start <= lastColumn; start += 2) {
      const end = start + 1;
      const isOccupied = occupied.has(seatIdentifier(row, start)) || occupied.has(seatIdentifier(row, end));
      items.push({ kind: 'couch', row, start, end, state: isOccupied ? 'unavailable' : 'available' });
    }
    return items;
  }
  for (let column = firstColumn; column <= lastColumn; column++) {
    items.push({ kind: 'seat', row, column, state: seatState(row, column, occupied) });
  }
  return items;
}

function seatState(row: number, column: number, occupied: ReadonlySet<string>): SeatState {
  if (occupied.has(seatIdentifier(row, column))) {
    return 'unavailable';
  }
  const isAccessible =
    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
  return isAccessible ? 'accessible' : 'available';
}
import { Component, computed, effect, inject, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { CinemaApi } from '../cinema-api';
import { formatShowDate } from '../dates';
import { buildAuditorium } from './auditorium';

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });
  private readonly screeningId = computed(() => Number(this.params().get('id')));

  protected readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }) => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  protected readonly rows = computed(() => {
    const screening = this.data.value()?.screening;
    return buildAuditorium(new Set(screening?.occupiedSeats ?? []));
  });

  constructor() {
    // A screening that cannot be loaded (404 or any other failure) sends the customer back to the movie list.
    effect(() => {
      if (this.data.error()) {
        void this.router.navigate(['/']);
      }
    });
  }

  protected showDate(date: string, time: string): string {
    return formatShowDate(date, time);
  }
}
