export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatItem {
  kind: 'seat';
  row: number;
  column: number;
  state: SeatState;
}

export interface CouchItem {
  kind: 'couch';
  row: number;
  start: number;
  end: number;
  state: SeatState;
}

export type AuditoriumItem = SeatItem | CouchItem;

/** One row of the auditorium: the three blocks between the two aisles, left to right. */
export interface AuditoriumRow {
  number: number;
  blocks: AuditoriumItem[][];
}

const ROW_COUNT = 15;
const COUCH_ROW = 15;
/** Rows 1 to 10 have no seats in columns 1 to 4: the entrance. */
const ENTRANCE_LAST_ROW = 10;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

export function seatIdentifier(row: number, column: number): string {
  return `R${row}C${column}`;
}

/** The seat identifiers an item occupies: one for a seat, two for a couch. */
export function identifiersOf(item: AuditoriumItem): string[] {
  return item.kind === 'seat'
    ? [seatIdentifier(item.row, item.column)]
    : [seatIdentifier(item.row, item.start), seatIdentifier(item.row, item.end)];
}

/** The seat description used in the selected-seats panel: the column, or `<a>-<b>` for a couch. */
export function seatLabel(item: AuditoriumItem): string {
  return item.kind === 'seat' ? String(item.column) : `${item.start}-${item.end}`;
}

/**
 * Builds the auditorium: rows 1 to 15, each split into blocks of columns 1–4, 5–20 and 21–24.
 * An item is unavailable when any of its identifiers is occupied, selected when all of its
 * identifiers are in `selectedSeats`.
 */
export function buildAuditorium(
  occupiedSeats: ReadonlySet<string>,
  selectedSeats: ReadonlySet<string>,
): AuditoriumRow[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const number = index + 1;
    const left = number <= ENTRANCE_LAST_ROW ? [] : itemsFor(number, 1, 4, occupiedSeats, selectedSeats);
    return {
      number,
      blocks: [
        left,
        itemsFor(number, 5, 20, occupiedSeats, selectedSeats),
        itemsFor(number, 21, 24, occupiedSeats, selectedSeats),
      ],
    };
  });
}

function itemsFor(
  row: number,
  firstColumn: number,
  lastColumn: number,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
): AuditoriumItem[] {
  const items: AuditoriumItem[] = [];
  if (row === COUCH_ROW) {
    for (let start = firstColumn; start <= lastColumn; start += 2) {
      const end = start + 1;
      const state = stateOf([seatIdentifier(row, start), seatIdentifier(row, end)], false, occupied, selected);
      items.push({ kind: 'couch', row, start, end, state });
    }
    return items;
  }
  for (let column = firstColumn; column <= lastColumn; column++) {
    const isAccessible =
      row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
    const state = stateOf([seatIdentifier(row, column)], isAccessible, occupied, selected);
    items.push({ kind: 'seat', row, column, state });
  }
  return items;
}

function stateOf(
  identifiers: readonly string[],
  accessible: boolean,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
): SeatState {
  if (identifiers.some((id) => occupied.has(id))) {
    return 'unavailable';
  }
  if (identifiers.every((id) => selected.has(id))) {
    return 'selected';
  }
  return accessible ? 'accessible' : 'available';
}

import { Component, inject, Injectable } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar } from '@angular/material/snack-bar';

/** Content of a toast: the message text carries the `toast` test id. */
@Component({
  selector: 'app-toast',
  template: `<span data-testid="toast">{{ message }}</span>`,
})
export class ToastMessage {
  protected readonly message = inject<string>(MAT_SNACK_BAR_DATA);
}

/** Shows short messages as toasts. A toast stays for 4 seconds; a new one replaces the current one. */
@Injectable({ providedIn: 'root' })
export class Toaster {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastMessage, { data: message, duration: 4000 });
  }
}

import { Component, computed, effect, inject, linkedSignal, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButton } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { CinemaApi } from '../cinema-api';
import { formatShowDate } from '../dates';
import { Toaster } from '../toast/toast';
import { AuditoriumItem, buildAuditorium, identifiersOf, seatLabel, SeatState } from './auditorium';

const MAX_SEATS_PER_BOOKING = 10;

@Component({
  selector: 'app-seat-selection',
  imports: [MatButton],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toaster = inject(Toaster);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });
  private readonly screeningId = computed(() => Number(this.params().get('id')));

  protected readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }) => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  /** Identifiers of the selected seats; a couch contributes both of its identifiers. Cleared when the screening changes. */
  protected readonly selected = linkedSignal<ReadonlySet<string>>({
    source: this.screeningId,
    computation: () => new Set<string>(),
  });

  protected readonly selectedCount = computed(() => this.selected().size);

  protected readonly rows = computed(() => {
    const screening = this.data.value()?.screening;
    return buildAuditorium(new Set(screening?.occupiedSeats ?? []), this.selected());
  });

  /** One line per row with a selection, in ascending row order. */
  protected readonly selectedRows = computed(() =>
    this.rows()
      .map((row) => ({
        row: row.number,
        seats: row.blocks.flat().filter((item) => item.state === 'selected').map(seatLabel),
      }))
      .filter((line) => line.seats.length > 0)
      .map((line) => ({ row: line.row, text: `Row ${line.row}: ${line.seats.join(', ')}` })),
  );

  protected readonly legend: { state: SeatState; label: string }[] = [
    { state: 'available', label: 'Available' },
    { state: 'selected', label: 'Selected' },
    { state: 'unavailable', label: 'Unavailable' },
    { state: 'accessible', label: 'Accessible' },
  ];

  constructor() {
    // A screening that cannot be loaded (404 or any other failure) sends the customer back to the movie list.
    effect(() => {
      if (this.data.error()) {
        void this.router.navigate(['/']);
      }
    });
  }

  protected showDate(date: string, time: string): string {
    return formatShowDate(date, time);
  }

  protected toggle(item: AuditoriumItem): void {
    if (item.state === 'unavailable') {
      return;
    }
    const identifiers = identifiersOf(item);
    const current = this.selected();
    if (item.state === 'selected') {
      this.selected.set(new Set([...current].filter((id) => !identifiers.includes(id))));
      return;
    }
    if (current.size + identifiers.length > MAX_SEATS_PER_BOOKING) {
      this.toaster.show(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
      return;
    }
    this.selected.set(new Set([...current, ...identifiers]));
  }

  protected onCancel(): void {
    this.selected.set(new Set<string>());
    void this.router.navigate(['/']);
  }

  protected onContinue(): void {
    if (this.selectedCount() === 0) {
      return;
    }
    void this.router.navigate(['/screenings', this.screeningId(), 'summary']);
  }
}

